import {createTerminal} from './terminal.js';
import {startMotion} from './motion.js';
import {startLandingDemos} from './landing-demos.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const price=(n,max)=>Number.isFinite(n)?'$'+n.toLocaleString('en-US',{minimumFractionDigits:n<.01?4:2,maximumFractionDigits:max??(n<.01?8:2)}):'—';
const compact=n=>Number.isFinite(n)?'$'+Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n):'—';
const percent=n=>Number.isFinite(n)?(n>=0?'+':'')+n.toFixed(2)+'%':'—';
const read=(key,fallback=[])=>{try{const v=JSON.parse(localStorage.getItem('solvia:'+key)??localStorage.getItem('solveil:'+key));return Array.isArray(fallback)?(Array.isArray(v)?v:fallback):(v&&typeof v==='object'?v:fallback);}catch{return fallback;}};
const write=(key,value)=>{try{localStorage.setItem('solvia:'+key,JSON.stringify(value));return true;}catch{toast('Local storage is full or unavailable. Export your draft instead.');return false;}};
let data=null,refreshing=false,wallet=null,walletProvider=null,connectedStandard=null,solBalance=null,positions=read('positions').filter(p=>['SOL','BTC','ETH'].includes(p.symbol)&&Number.isFinite(p.entry)&&Number.isFinite(p.margin)),watchlist=read('watchlist'),draftImage='',currentDraftId=null,appSymbol='SOL',appSide='long',appLeverage=3,appMargin=100,appRange=30,appTable='Market info',swapReversed=false,poolSavedOnly=false;
const market=symbol=>data?.markets?.find(m=>m.symbol===symbol);
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied');}catch{toast('Copy is unavailable in this browser. Use Export JSON.');}}
const dateText=()=>data?.asOf?new Date(data.asOf).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'unavailable';
const sourceLabel=()=>`${data?.snapshot?'Saved snapshot':'Updated'} ${dateText()} · Binance reference / DexScreener pools`;
function applyMarketText(){
 $$('[data-price]').forEach(el=>el.textContent=price(market(el.dataset.price)?.price));$$('[data-change]').forEach(el=>{const n=market(el.dataset.change)?.change;el.textContent=percent(n);el.classList.toggle('bad',n<0);el.classList.toggle('good',n>=0);});
 $('#chain-status').textContent=data?.network?.slot?`SOLANA MAINNET · SLOT ${Number(data.network.slot).toLocaleString('en-US')}`:'SOLANA MAINNET · STATUS UNAVAILABLE';
 $('#market-state').textContent=sourceLabel();
 const tape=data?.tape||[];$('#trade-tape').innerHTML=tape.length?tape.slice(0,7).map(t=>`<div class="trade-row"><span class="${t.side==='Buy'?'good':'bad'}">${t.side}</span><span>${t.quantity.toFixed(3)} SOL</span><span>${t.price.toFixed(2)}</span><span class="muted">${new Date(t.time).toLocaleTimeString('en-GB',{hour12:false})}</span></div>`).join(''):'<p class="empty">Trade reference unavailable. No invented activity.</p>';
}
async function refreshData(){if(refreshing)return;refreshing=true;try{const res=await fetch('/api/markets',{cache:'no-store',signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error();const next=await res.json();if(!Array.isArray(next.markets))throw Error();data=next;applyMarketText();motion.refresh();landingDemos.refresh();if(location.pathname.startsWith('/app/'))refreshAppValues();}catch{if(!data){$('#market-state').textContent='Market sources unavailable · try refresh in the app';$('#chain-status').textContent='SOLANA MAINNET · CONNECTION UNAVAILABLE';}}finally{refreshing=false;}}
const configs=[{file:'launch.config.json',code:'{\n  "network": "solana:mainnet",\n  "name": "Your next idea",\n  "symbol": "IDEA",\n  "venue": "pump.fun",\n  "status": "local-draft",\n  "requiresWalletReview": true\n}'},{file:'your-launchpad.html',code:'<main class="your-world">\n  <h1>Your idea. Your market.</h1>\n\n  <!-- Keep the identity yours. -->\n  <a href="/app/launch">\n    Prepare a launch\n  </a>\n</main>'},{file:'launch-checklist.txt',code:'01  Confirm the name and ticker.\n02  Check the artwork and links.\n03  Export a copy of your draft.\n04  Open the chosen launch venue.\n05  Review its fees and token rules.\n06  Review and sign in your wallet.\n\nNo automatic signing. Your decision.'}];
let builderStep=0;function renderBuilder(){const config=configs[builderStep];$('#code-title').textContent=config.file;$('#builder-code').textContent=config.code;$$('[data-code]').forEach(b=>b.classList.toggle('active',Number(b.dataset.code)===builderStep));$$('[data-build]').forEach(b=>b.classList.toggle('active',Number(b.dataset.build)===builderStep));}
$$('[data-build]').forEach(b=>b.addEventListener('click',()=>{builderStep=Number(b.dataset.build);renderBuilder();}));$$('[data-code]').forEach(b=>b.addEventListener('click',()=>{builderStep=Number(b.dataset.code);renderBuilder();}));$('#copy-config').addEventListener('click',()=>copy(configs[builderStep].code));renderBuilder();
$$('[data-control]').forEach(b=>b.addEventListener('click',()=>{$$('[data-control]').forEach(el=>el.classList.toggle('active',el===b));$('.flow-ring').style.stroke=['#80f4c6','#14f195','#ffffff'][Number(b.dataset.control)];}));
$('.menu').addEventListener('click',()=>$('.header').classList.toggle('menu-open'));addEventListener('scroll',()=>document.body.classList.toggle('scrolled',scrollY>15),{passive:true});
const wallets=new Map();function register(...items){for(const w of items)if(w&&typeof w.name==='string'&&w.features?.['standard:connect'])wallets.set(w.name,w);return()=>items.forEach(w=>wallets.delete(w.name));}const walletRegistry=Object.freeze({register});addEventListener('wallet-standard:register-wallet',event=>{if(typeof event.detail==='function')event.detail(walletRegistry);});dispatchEvent(new CustomEvent('wallet-standard:app-ready',{detail:walletRegistry}));
function updateWalletUI(){const title=wallet?wallet.slice(0,4)+'…'+wallet.slice(-4):'Connect wallet';$$('.connect').forEach(b=>b.textContent=title);if(['/app/wallet','/app/vault'].includes(location.pathname))renderApp();else if(location.pathname.startsWith('/app/'))refreshAppValues();}
async function readBalance(){solBalance=null;if(!wallet)return;try{const r=await fetch('/api/balance?address='+encodeURIComponent(wallet),{cache:'no-store',signal:AbortSignal.timeout(15000)});const j=await r.json();if(j.address===wallet&&Number.isFinite(j.lamports))solBalance=j.lamports/1e9;}catch{}updateWalletUI();}
function openWallet(){if(wallet){navigate('/app/vault');return;}$('#wallet-message').textContent='';$('#wallet-modal').showModal();}
async function connectWallet(name){$('#wallet-message').textContent='Waiting for your wallet…';try{const discovered=[...wallets.values()].find(w=>w.name.toLowerCase().includes(name));let account;if(discovered){const result=await discovered.features['standard:connect'].connect();account=result.accounts.find(a=>a.chains?.some(c=>c.startsWith('solana:')));if(!account)throw Error('No Solana account was shared.');connectedStandard=discovered;walletProvider=null;}else if(name==='phantom'&&window.phantom?.solana?.isPhantom){walletProvider=window.phantom.solana;const result=await walletProvider.connect();account={address:result.publicKey.toString()};walletProvider.on?.('accountChanged',key=>{wallet=key?.toString()||null;solBalance=null;updateWalletUI();if(wallet)readBalance();});walletProvider.on?.('disconnect',()=>{wallet=null;solBalance=null;updateWalletUI();});}else{throw Error(`${name==='phantom'?'Phantom':'Backpack'} was not detected. Install its extension, then reload this page.`);}if(!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(account.address))throw Error('A valid Solana account was not shared.');wallet=account.address;$('#wallet-modal').close();updateWalletUI();readBalance();toast('Connected · public address only');}catch(e){$('#wallet-message').textContent=e.code===4001?'Connection cancelled.':e.message||'Wallet connection unavailable.';}}
$$('[data-wallet]').forEach(b=>b.addEventListener('click',()=>connectWallet(b.dataset.wallet)));$('[data-close-dialog]').addEventListener('click',()=>$('#wallet-modal').close());$('#wallet-modal').addEventListener('click',e=>{if(e.target===$('#wallet-modal'))$('#wallet-modal').close();});
document.addEventListener('click',e=>{const connect=e.target.closest('.connect');if(connect){e.preventDefault();openWallet();return;}const anchor=e.target.closest('a');if(!anchor||e.defaultPrevented||e.ctrlKey||e.metaKey||anchor.target==='_blank'||anchor.hasAttribute('download'))return;const url=new URL(anchor.href,location.href);if(url.origin===location.origin){if(url.pathname===location.pathname&&url.hash)return;if(['/','/docs','/developers'].includes(url.pathname)||url.pathname.startsWith('/app/')){e.preventDefault();navigate(url.pathname+url.search+url.hash);}}});
function navigate(url){history.pushState({},'',url);route();window.scrollTo({top:0,behavior:'instant'});$('.header').classList.remove('menu-open');}addEventListener('popstate',route);
function route(){const pathname=location.pathname,isApp=pathname.startsWith('/app/'),isDocs=['/docs','/developers'].includes(pathname);document.body.classList.toggle('in-app',isApp);document.body.classList.toggle('in-docs',isDocs);$('#home-view').classList.toggle('hidden',isApp||isDocs);$('#app-view').classList.toggle('hidden',!isApp);$('#docs-view').classList.toggle('hidden',!isDocs);$('.header-launch').classList.toggle('hidden',isApp);$('.header .connect').classList.toggle('hidden',!isApp);$('#top-nav').innerHTML=isApp?[['Perps','perps'],['Swap','swap'],['Pools','pools'],['Launches','launch'],['Vault','vault']].map(([label,slug])=>`<a href="/app/${slug}" class="${pathname.startsWith('/app/'+slug)?'active':''}">${label}</a>`).join(''):'<a href="/docs">Docs</a><a href="/developers">Developers</a>';if(isApp)renderApp();if(isDocs)renderDocs(pathname==='/developers');document.title=(isApp?pathname.split('/').at(-1).replace(/^./,s=>s.toUpperCase())+' · ':isDocs?'Docs · ':'')+'Solvia';if(!isApp&&!isDocs)requestAnimationFrame(()=>motion.refresh());if(location.hash)setTimeout(()=>$(location.hash)?.scrollIntoView(),40);updateConnectText();}
function updateConnectText(){$$('.connect').forEach(b=>b.textContent=wallet?wallet.slice(0,4)+'…'+wallet.slice(-4):'Connect wallet');}
function renderApp(){terminal.render(location.pathname);updateConnectText();}
function refreshAppValues(){terminal.refresh();}
function renderDocs(developer=false){$('#docs-view').innerHTML=`<div class="wrap docs-layout"><nav class="docs-sidebar"><strong>FOR EVERYONE</strong><a href="/docs">Overview</a><a href="/docs#status">Product status</a><a href="/docs#sources">Data sources</a><a href="/docs#wallet">Wallet connection</a><a href="/docs#risk">Model limits</a><strong>FOR BUILDERS</strong><a href="/developers">Developer notes</a><a href="/app/launch">Launch draft studio</a></nav><article class="docs-content">${developer?`<p class="eyebrow mono">DEVELOPERS</p><h1>A Solana workspace.<br><em>Clear boundaries.</em></h1><p>Solvia is a visual preview and public-data workspace. It is independent of Curveil and does not operate Curveil's contracts on Solana.</p><h2>Public market endpoint</h2><p><code>GET /api/markets</code> reads SOL, BTC, ETH, XRP, BNB and DOGE market context, a Solana pool sample and the Solana slot. The response contains a source timestamp and a <code>snapshot</code> flag when only saved data is available.</p><pre>{\n  "asOf": "ISO source retrieval time",\n  "snapshot": false,\n  "markets": [],\n  "pools": [],\n  "tape": [],\n  "network": { "slot": 0 }\n}</pre><h2>Launch drafts</h2><p>Drafts are stored in this browser, never broadcast as token launches. Export/import supports a token name, ticker, description, HTTPS links and an optional PNG/JPEG/WebP image. The venue performs the real launch.</p><h2>Wallet model</h2><p>Wallet Standard discovery and Phantom's Solana provider are used for public-address connection. <code>GET /api/balance?address=...</code> reads a confirmed native SOL balance. There is no message signing, private-key collection, custodial account or transaction broadcast endpoint.</p><h2>Execution integrations</h2><p>Swaps hand off to <a href="https://jup.ag/swap" target="_blank" rel="noopener">Jupiter</a>. Launch drafts hand off to <a href="https://pump.fun/create" target="_blank" rel="noopener">pump.fun</a>. Pool links come from the returned DexScreener pair data. This preview has no custom mint factory, fee splitter or shielded Solana program.</p>`:`<p class="eyebrow mono">OVERVIEW</p><h1>Open markets.<br><em>Solana native.</em></h1><p>One place to explore public markets, understand a hypothetical position and prepare a launch. Solvia combines public market references with Solana pool discovery, launch preparation and a local position model.</p><h2 id="status">What works today</h2><table><thead><tr><th>Feature</th><th>Current behavior</th></tr></thead><tbody><tr><td>Public markets</td><td>API-backed reference prices and Solana pool discovery.</td></tr><tr><td>Wallet</td><td>Public Solana address and native SOL balance only.</td></tr><tr><td>Perps</td><td>Local simulation. No order is opened.</td></tr><tr><td>Swap</td><td>Indicative calculation and explicit Jupiter handoff.</td></tr><tr><td>Launches</td><td>Local drafts, image preview, JSON import/export and pump.fun handoff.</td></tr><tr><td>Privacy vault</td><td>Not implemented. No private-transfer or shielding claim.</td></tr><tr><td>Project token</td><td>No mint supplied. CA soon.</td></tr></tbody></table><h2 id="sources">Where the data comes from</h2><p>Prices, intraday and daily candles, and SOL/USDT trade references come from Binance's public market-data API. They are exchange reference prices, not executions by this application. Pool liquidity, volume and pair links come from <a href="https://docs.dexscreener.com/api/reference" target="_blank" rel="noopener">DexScreener</a>, filtered to Solana. The pool list is a fetched sample, not the entire chain.</p><p>Data is refreshed every 30 seconds while this page is visible. If a source fails, saved data is explicitly marked as a snapshot with its original retrieval time; unavailable fields show a dash.</p><h2 id="wallet">Connecting your wallet</h2><p>Use a Solana wallet such as Phantom or a Wallet Standard-compatible Backpack installation. Connection shares your public address. Reading the SOL balance sends that address to Solana's public RPC. No signature is needed and no funds move.</p><h2 id="risk">Model limits</h2><p>The paper model uses a fixed 2% maintenance margin and ignores fees, funding, slippage, oracle differences, collateral changes and venue rules. Its liquidation estimate is educational. Saved positions are local simulations, not claims on real assets.</p><p>The launch lifecycle and liquidity distribution on the home page are visual explanations. They are not live token launches or audited liquidity rules. Actual terms, fees and signing happen on the external venue you choose.</p><h2>Independent by design</h2><p>Solvia is not affiliated with Curveil, Solana Foundation, Jupiter, Binance or pump.fun. Follow <a href="https://x.com/Solviatech" target="_blank" rel="noopener">@Solviatech</a> for project updates. No official token address has been announced.</p>`}</article></div>`;}
const terminal=createTerminal({read,write,toast,download,copy,navigate,sourceLabel,refreshData,readBalance,market,data:()=>data,wallet:()=>({address:wallet,balance:solBalance}),disconnect:async()=>{try{if(connectedStandard?.features?.['standard:disconnect'])await connectedStandard.features['standard:disconnect'].disconnect();else await walletProvider?.disconnect?.();}catch{}wallet=null;walletProvider=null;connectedStandard=null;solBalance=null;updateWalletUI();toast('Disconnected');}});
const landingDemos=startLandingDemos(()=>data);
const motion=startMotion(()=>data);route();refreshData();setInterval(()=>{if(!document.hidden)refreshData();},30000);addEventListener('resize',()=>{motion.refresh();landingDemos.refresh();terminal.refresh();});
